function matchesTask(task, filter, prioritySelection, range, query) {
  return matchesSearch(task.title, query) &&
    (filter === 'Deleted' ? Boolean(task.deleted) : !task.deleted &&
      (filter === 'All' || Boolean(task.completed) === (filter === 'Completed'))) &&
    (prioritySelection === 'All' || task.priority === prioritySelection) &&
    ((!range.from && !range.through) || (task.due_date &&
      (!range.from || task.due_date >= range.from) &&
      (!range.through || task.due_date <= range.through)));
}

function matchingDirectoryTasks(scope, filter, prioritySelection, range, query) {
  return directoryTasks.all(scope === 'Archived' ? 1 : 0)
    .filter(task => matchesTask(task, filter, prioritySelection, range, query));
}

function directoryOrder(value) {
  return ['Original', 'Priority', 'Due date', 'Title'].includes(value) ? value : 'Original';
}

function compareTitles(left, right) {
  const fold = title => Array.from(title.replace(/[A-Z]/g, letter => letter.toLowerCase()), character => character.codePointAt(0));
  const a = fold(left);
  const b = fold(right);
  for (let index = 0; index < Math.min(a.length, b.length); index++) {
    if (a[index] !== b[index]) return a[index] - b[index];
  }
  return a.length - b.length;
}

function orderDirectoryTasks(tasks, order) {
  // Stable sorting retains Original order for equal keys; never alter stored positions.
  if (order === 'Priority') {
    const rank = { High: 0, Normal: 1, Low: 2 };
    tasks.sort((a, b) => rank[a.priority] - rank[b.priority]);
  } else if (order === 'Due date') {
    tasks.sort((a, b) => {
      if (!a.due_date || !b.due_date) return Number(!a.due_date) - Number(!b.due_date);
      return a.due_date < b.due_date ? -1 : a.due_date > b.due_date ? 1 : 0;
    });
  } else if (order === 'Title') {
    tasks.sort((a, b) => compareTitles(a.title, b.title));
  }
  return tasks;
}

function directoryPage(scope, filter, prioritySelection, range, query, error = '', rangeInput = range, order = 'Original') {
  const tasks = matchingDirectoryTasks(scope, filter, prioritySelection, range, query);
  // Group by identity in Original order before applying the task-only view sort.
  const owners = new Map();
  for (const task of tasks) {
    if (!owners.has(task.project_id)) {
      owners.set(task.project_id, { id: task.project_id, name: task.project_name, total: 0, completed: 0 });
    }
    const owner = owners.get(task.project_id);
    owner.total++;
    if (task.completed) owner.completed++;
  }
  orderDirectoryTasks(tasks, order);
  const editable = scope === 'Active' && filter !== 'Deleted';
  const selections = `<input type="hidden" name="order" value="${order}">
    <input type="hidden" name="scope" value="${scope}">
    <input type="hidden" name="filter" value="${filter}">
    <input type="hidden" name="priorityFilter" value="${prioritySelection}">`;
  const select = (label, name, values, selected) => `<label for="directory-${name}">${label}</label>
    <select id="directory-${name}" name="${name}" onchange="this.form.requestSubmit()">
      ${values.map(value => `<option${value === selected ? ' selected' : ''}>${value}</option>`).join('')}
    </select>`;
  return page(`<h1>Task directory</h1>
    <form action="/" method="get"><button type="submit">Projects</button></form>
    ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
    <form action="/directory" method="get">
      ${rangeFields(range)}${searchField(query)}
      ${select('Project scope', 'scope', ['Active', 'Archived'], scope)}
      ${select('Task filter', 'filter', ['All', 'Open', 'Completed', 'Deleted'], filter)}
      ${select('Priority filter', 'priorityFilter', ['All', ...priorities], prioritySelection)}
      ${select('Directory order', 'order', ['Original', 'Priority', 'Due date', 'Title'], order)}
    </form>
    <form action="/directory" method="get">
      ${selections}${rangeFields(range)}
      <label for="directory-search">Directory search</label>
      <input id="directory-search" name="search" value="${escapeHtml(query)}" autocomplete="off">
      <button type="submit">Search directory</button>
    </form>
    <form action="/directory/due-range" method="post">
      ${selections}${rangeFields(range)}${searchField(query)}
      <label for="directory-due-from">Due from</label>
      <input id="directory-due-from" name="rangeFrom" value="${escapeHtml(rangeInput.from)}" autocomplete="off">
      <label for="directory-due-through">Due through</label>
      <input id="directory-due-through" name="rangeThrough" value="${escapeHtml(rangeInput.through)}" autocomplete="off">
      <button type="submit">Apply due range</button>
    </form>
    <form action="/directory/completion" method="post">
      ${selections}${rangeFields(range)}${searchField(query)}
      <button type="submit" name="completed" value="1"${!editable || !tasks.some(task => !task.completed) ? ' disabled' : ''}>Complete visible tasks</button>
      <button type="submit" name="completed" value="0"${!editable || !tasks.some(task => task.completed) ? ' disabled' : ''}>Reopen visible tasks</button>
    </form>
    <form action="/directory/deletion" method="post">
      ${selections}${rangeFields(range)}${searchField(query)}
      <button type="submit" name="deleted" value="1"${!editable || tasks.length === 0 ? ' disabled' : ''}>Delete visible tasks</button>
      <button type="submit" name="deleted" value="0"${scope !== 'Active' || filter !== 'Deleted' || tasks.length === 0 ? ' disabled' : ''}>Restore visible tasks</button>
    </form>
    <p data-testid="directory-summary">${tasks.filter(task => task.completed).length}/${tasks.length} completed</p>
    <section aria-label="Directory projects">
      ${[...owners.values()].map(owner => `<div class="project" data-testid="directory-owner-row">
        <span data-testid="directory-owner-name">${escapeHtml(owner.name)}</span>
        <span data-testid="directory-owner-summary">${owner.completed}/${owner.total} completed</span>
        <form action="/projects/${owner.id}" method="get"><button type="submit">Open project</button></form>
      </div>`).join('')}
    </section>
    <section aria-label="Directory tasks">
      ${tasks.length === 0 ? '<p id="directory-empty" role="status">No matching tasks</p>' : ''}
      ${tasks.map(task => `<div class="project" data-testid="directory-task-row">
        <span data-testid="directory-task-title">${escapeHtml(task.title)}</span>
        <span data-testid="directory-project-name">${escapeHtml(task.project_name)}</span>
        <span data-testid="directory-task-completion">${task.completed ? 'Completed' : 'Open'}</span>
        <span data-testid="directory-task-priority">${escapeHtml(task.priority)}</span>
        <span data-testid="directory-task-due-date">${escapeHtml(task.due_date)}</span>
        <span data-testid="directory-task-notes" style="white-space: pre-wrap">${escapeHtml(task.notes)}</span>
        <form action="/projects/${task.project_id}" method="get"><button type="submit">Open project</button></form>
      </div>`).join('')}
    </section>
    <script>
      // Full-page responses contain resolved results; hide the old empty state during navigation.
      const emptyState = document.getElementById('directory-empty');
      document.addEventListener('submit', () => {
        if (emptyState) emptyState.hidden = true;
      });
      window.addEventListener('pageshow', () => {
        if (emptyState) emptyState.hidden = false;
      });
    </script>`);
